for directory in ['experiments/e1','experiments/e2','experiments/e3']:
 for p in Path(directory).rglob('*'):
  if p.is_file() and p.suffix in ('.md','.txt','.py'):
   text=p.read_text()
   if any(word in text.lower() for word in ['gluing','graph-angle','graph projections','metric-complete','metric complete']):
    print('\n###',p)
    for i,line in enumerate(text.splitlines()):
     if any(word in line.lower() for word in ['gluing','graph-angle','graph projections','metric-complete','metric complete']):
      print('\n'.join(text.splitlines()[max(0,i-5):i+12]))

